#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include "Halide.h"

// include common definitions (PolyBench sizes & DATA_TYPE)
#include "defines.hpp"

// include benchmark-specific definitions (N, DATA_TYPE, etc)
#include "ludcmp.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

// -----------------------------------------------------------------------------
// Tunable scheduling constants
// -----------------------------------------------------------------------------
// These constants control tile and vector sizes used in the Halide schedules.
// They are conservative defaults for a modern x86_64 CPU; you can tune them
// for a specific machine if desired.
static constexpr int kInitTileI   = 256;                    // 1D init tile
static constexpr int kSPDTileX    = 32;                     // SPD tile in x (col)
static constexpr int kSPDTileY    = 32;                     // SPD tile in y (row)
static constexpr int kVectorWidth = (sizeof(num_t) == 8)    // 4 doubles or 8 floats
                                        ? 4
                                        : 8;

/**
 * Initialize A, b, x, y the same way as the original C init_array().
 *
 * Original C:
 *   for i:
 *     x[i] = 0;
 *     y[i] = 0;
 *     b[i] = (i+1)/fn/2.0 + 4;
 *
 *   A initial lower-triangular construction, then:
 *     B = A * A^T;
 *     A = B;
 *
 * We implement the heavy parts (init of A and B = A*A^T) with Halide Funcs
 * and add an explicit schedule (tiling, parallelization, vectorization) to
 * improve data locality and throughput.
 */
static void init_array(int n,
                       Halide::Buffer<num_t, 2> &A,   // shape (n, n): (x=col, y=row)
                       Halide::Buffer<num_t, 1> &b,   // shape (n)
                       Halide::Buffer<num_t, 1> &x,   // shape (n)
                       Halide::Buffer<num_t, 1> &y) { // shape (n)
    Var i("i"), col("col"), row("row");

    // Use the host JIT target so that scheduling (especially vectorization)
    // is appropriate for the actual machine we are running on.
    Target target = get_jit_target_from_environment();

    // -----------------------------
    // 1) Initialize x, y, and b
    // -----------------------------
    //
    // x[i] = 0;
    // y[i] = 0;
    // b[i] = (i+1)/n/2.0 + 4;
    //
    // Implemented as three simple 1D Funcs which we schedule with
    // moderate tiling + vectorization + parallelization.

    Func init_x("init_x"), init_y("init_y"), init_b("init_b");

    Expr fn    = cast<num_t>(n);
    Expr half  = cast<num_t>(0.5);
    Expr four  = cast<num_t>(4.0);

    init_x(i) = cast<num_t>(0.0);
    init_y(i) = cast<num_t>(0.0);

    // term = (i+1)/n/2 + 4
    Expr term = (cast<num_t>(i + 1) / fn) * half + four;
    init_b(i) = term;

    // Schedule: 1D tiling in i, vectorize the inner tile, parallelize outer.
    {
        Var io("io"), ii("ii");
        init_x
            .compute_root()
            .split(i, io, ii, kInitTileI)
            .vectorize(ii, kVectorWidth)
            .parallel(io);

        init_y
            .compute_root()
            .split(i, io, ii, kInitTileI)
            .vectorize(ii, kVectorWidth)
            .parallel(io);

        init_b
            .compute_root()
            .split(i, io, ii, kInitTileI)
            .vectorize(ii, kVectorWidth)
            .parallel(io);
    }

    init_x.realize(x, target);
    init_y.realize(y, target);
    init_b.realize(b, target);

    // ----------------------------------------
    // 2) Build initial lower-triangular A_init
    // ----------------------------------------
    //
    // A_init[row=i, col=j] =
    //   1                      if j == i
    //   (-j % n) / n + 1       if j <= i (strictly lower triangular part)
    //   0                      otherwise
    //
    // In our storage layout we store A(row=i, col=j) as A(j, i), i.e.,
    // first dimension is column, second is row.
    //
    // We'll materialize A_init as a full n x n buffer to avoid recomputing
    // the simple expression inside the O(n^3) SPD matmul below.

    Func A_init("A_init");

    // (-j % n) / n + 1  -> implement as -(j % n)/n + 1
    Expr neg_mod = -(col % n); // integer expression
    Expr base    = cast<num_t>(neg_mod) / fn + cast<num_t>(1.0);

    A_init(col, row) =
        select(col == row,
               cast<num_t>(1.0),                // diagonal = 1
               select(col <= row,
                      base,                     // lower triangle
                      cast<num_t>(0.0)));       // upper triangle = 0

    // Schedule A_init as a 2D array:
    //  - parallelize over rows
    //  - tile and vectorize along columns (fastest-varying dimension)
    {
        Var co("co"), ci("ci");
        A_init
            .compute_root()
            .split(col, co, ci, 64)             // 64 columns per tile
            .vectorize(ci, kVectorWidth)        // contiguous in memory
            .parallel(row);
    }

    // ------------------------------------
    // 3) Symmetric positive-definite SPD
    // ------------------------------------
    //
    // Compute B = A_init * A_init^T, then store B into A.
    //
    // B[row=r, col=s] = sum_t A_init[r, t] * A_init[s, t]
    //
    // In our layout: A(row=r, col=s) is A(s, r), so:
    //   SPD(col=s, row=r) = sum_t A_init(t, r) * A_init(t, s)
    //
    // This is an O(n^3) matrix multiply; we heavily schedule it for locality:
    //  - tile in (col,row) for better cache use
    //  - parallelize across tiles
    //  - vectorize across columns inside each tile

    Func SPD("SPD");
    RDom k(0, n, "k");

    SPD(col, row) = cast<num_t>(0.0);
    SPD(col, row) += A_init(k, row) * A_init(k, col);

    {
        Var xo("xo"), yo("yo"), xi("xi"), yi("yi"), tile("tile");

        SPD
            .compute_root()
            // 2D tiling over (col,row)
            .tile(col, row, xo, yo, xi, yi, kSPDTileX, kSPDTileY)
            // Parallelize across tiles (good for many-core CPUs)
            .fuse(xo, yo, tile)
            .parallel(tile)
            // Vectorize inside the tile along columns (contiguous memory)
            .vectorize(xi, kVectorWidth);
        // We leave the reduction dimension 'k' in its default innermost
        // position inside the (xi, yi) loops. This gives a simple
        // inner-product style loop for each (xi, yi) pair.
    }

    SPD.realize(A, target);
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // Buffers:
    // A: 2D (n x n), first dimension = column (j), second = row (i)
    // b, x, y: 1D (n)
    Halide::Buffer<num_t, 2> A(n, n);
    Halide::Buffer<num_t, 1> b(n), x(n), y(n);

    // Initialize data (now heavily scheduled for locality and parallelism)
    init_array(n, A, b, x, y);

    // Set up Halide parameters and ImageParams for the kernel.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam b_param(type_of<num_t>(), 1, "b_param");
    ImageParam x_param(type_of<num_t>(), 1, "x_param");
    ImageParam y_param(type_of<num_t>(), 1, "y_param");

    Param<int> pi("pi");  // current i
    Param<int> pj("pj");  // current j
    Param<int> pn("pn");  // n (for convenience in ranges)

    A_param.set(A);
    b_param.set(b);
    x_param.set(x);
    y_param.set(y);
    pn.set(n);

    // --------------------------------------------------------------------
    // Halide helpers for the LU decomposition and forward/back substitution
    //
    // IMPORTANT:
    // LU decomposition and triangular solves are inherently sequential
    // (strong loop-carried dependencies). Halide cannot express the full
    // algorithm as one large Func with legal update definitions, so we
    // follow the recommended pattern for dynamic programming / iterative
    // algorithms: define small pure Funcs that compute a *single* update
    // from the current matrix/vector state (passed in via ImageParams and
    // scalar Params), and drive the iteration with host-side for loops.
    //
    // We still express the inner dot-products as Halide reductions.
    // To reduce per-call overhead, each helper Func is 1D (extent 1) and
    // we reuse pre-allocated 1-element Buffers for the scalar outputs.
    // --------------------------------------------------------------------

    // 1) L-part update:
    // For j < i:
    //   w = A[i][j];
    //   for k = 0..j-1: w -= A[i][k] * A[k][j];
    //   A[i][j] = w / A[j][j];
    //
    // In our layout: A[i][j] == A_param(j, i).
    // We compute the new scalar A[i][j] as:
    //   A_param(pj, pi) - sum_{k=0..pj-1} A_param(k, pi) * A_param(pj, k)
    // then divide by A_param(pj, pj).
    Func update_L("update_L");
    {
        Var dummy("dummy_L"); // length-1 dimension for the scalar result

        RDom rL(0, pj, "rL");
        Expr sum_L = sum(A_param(rL, pi) * A_param(pj, rL));

        update_L(dummy) = (A_param(pj, pi) - sum_L) / A_param(pj, pj);
    }

    // 2) U-part update:
    // For j >= i:
    //   w = A[i][j];
    //   for k = 0..i-1: w -= A[i][k] * A[k][j];
    //   A[i][j] = w;
    //
    // In our layout: A[i][j] == A_param(j, i).
    // new A[i][j] = A_param(pj, pi) - sum_{k=0..pi-1} A_param(k, pi) * A_param(pj, k).
    Func update_U("update_U");
    {
        Var dummy("dummy_U");

        RDom rU(0, pi, "rU");
        Expr sum_U = sum(A_param(rU, pi) * A_param(pj, rU));

        update_U(dummy) = A_param(pj, pi) - sum_U;
    }

    // 3) Forward substitution for y:
    // For i = 0..n-1:
    //   w = b[i];
    //   for j = 0..i-1: w -= A[i][j] * y[j];
    //   y[i] = w;
    //
    // y[i] = b[i] - sum_{j=0..i-1} A[i][j] * y[j].
    // In our layout: A[i][j] == A_param(j, i).
    Func compute_y("compute_y");
    {
        Var dummy("dummy_y");

        RDom rY(0, pi, "rY");
        Expr sum_Y = sum(A_param(rY, pi) * y_param(rY));

        compute_y(dummy) = b_param(pi) - sum_Y;
    }

    // 4) Back substitution for x:
    // For i = n-1..0:
    //   w = y[i];
    //   for j = i+1..n-1: w -= A[i][j] * x[j];
    //   x[i] = w / A[i][i];
    //
    // x[i] = (y[i] - sum_{j=i+1..n-1} A[i][j] * x[j]) / A[i][i].
    // In our layout: A[i][j] == A_param(j, i).
    Func compute_x("compute_x");
    {
        Var dummy("dummy_x");

        // Domain j = i+1 .. n-1  -> RDom(pi+1, pn-(pi+1))
        RDom rX(pi + 1, pn - (pi + 1), "rX");
        Expr sum_X = sum(A_param(rX, pi) * x_param(rX));

        compute_x(dummy) = (y_param(pi) - sum_X) / A_param(pi, pi);
    }

    // Compile the small helper pipelines once.
    //
    // They are tiny (just a reduction + a few loads), so we don't add
    // custom schedules here; we rely on Halide's default schedule.
    update_L.compile_jit();
    update_U.compile_jit();
    compute_y.compile_jit();
    compute_x.compile_jit();

    // Reusable 1-element buffers to hold scalar outputs from the helpers.
    Halide::Buffer<num_t> tmp_L(1), tmp_U(1), tmp_y(1), tmp_x(1);

    // ------------------------------------
    // Run the kernel and measure its time.
    // ------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    // LU decomposition
    for (int i = 0; i < n; i++) {
        // L-part: j < i
        for (int j = 0; j < i; j++) {
            pi.set(i);
            pj.set(j);
            update_L.realize(tmp_L);
            // A[i][j] -> A(j, i)
            A(j, i) = tmp_L(0);
        }

        // U-part: j >= i
        for (int j = i; j < n; j++) {
            pi.set(i);
            pj.set(j);
            update_U.realize(tmp_U);
            A(j, i) = tmp_U(0);
        }
    }

    // Forward substitution to compute y
    for (int i = 0; i < n; i++) {
        pi.set(i);
        compute_y.realize(tmp_y);
        y(i) = tmp_y(0);
    }

    // Back substitution to compute x
    for (int i = n - 1; i >= 0; i--) {
        pi.set(i);
        compute_x.realize(tmp_x);
        x(i) = tmp_x(0);
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result vector x, similar to print_array().
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            if (i % 20 == 0) {
                std::cerr << '\n';
            }
            std::cerr << x(i) << ' ';
        }
        std::cerr << '\n';
    }

    // Print timing (seconds)
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
